insert into public.place_tags (place_sid, kind, label)
select w.place_sid, 'region', w.label
from wanted w
where not exists (
  select 1 from public.place_tags t
  where t.place_sid = w.place_sid
    and t.kind = 'region'
    and lower(trim(t.label)) = lower(trim(w.label))
);
